mapper.select:
SELECT NOTICE_ID, TITLE, CONTENT, CREATED_BY, CREATED_AT
  FROM NOTICE
 WHERE NOTICE_ID = #{noticeId}

mapper.update:
UPDATE NOTICE
   SET TITLE   = #{title},
       CONTENT = #{content}
 WHERE NOTICE_ID = #{noticeId}

mapper.select:
SELECT 0 AS NOTICE_ID, e.EMPNO, e.ENAME, NULL AS READ_AT
  FROM EMP e
 WHERE e.EMPNO NOT IN (
       SELECT nr.EMPNO FROM NOTICE_READ nr WHERE nr.NOTICE_ID = #{noticeId}
 )
 ORDER BY e.EMPNO

SELECT COUNT(*) FROM NOTICE n
 WHERE n.NOTICE_ID NOT IN (
       SELECT nr.NOTICE_ID FROM NOTICE_READ nr WHERE nr.EMPNO = #{empno}
 )
